@import "tailwindcss";

:root {
  --bg: #0c0a0d;
  --card: #161117;
  --ink: #f6e8ef;
  --muted: #c9a3b4;
  --accent: #e11d74;
  --gold: #d4af37;
  --line: #3a2430;
  --font-serif: "Palatino Linotype", Palatino, "Book Antiqua", "Times New Roman",
    serif;
}

@theme inline {
  --color-background: var(--bg);
  --color-foreground: var(--ink);
  --font-sans: var(--font-serif);
  --font-serif: var(--font-serif);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: var(--font-serif);
  background:
    radial-gradient(1200px 600px at 20% -10%, #3a1024 0%, var(--bg) 45%),
    var(--bg);
  color: var(--ink);
  line-height: 1.45;
}

.wrap {
  max-width: 880px;
  margin: 0 auto;
  padding: 28px 18px 80px;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 18px;
}

.field-label {
  display: block;
  font-size: 0.82rem;
  color: var(--muted);
  margin: 10px 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

input[type="text"],
input[type="date"],
textarea {
  width: 100%;
  background: #0e0b0f;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 12px;
  font: inherit;
}

textarea {
  min-height: 110px;
  resize: vertical;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

@media (max-width: 640px) {
  .row {
    grid-template-columns: 1fr;
  }
}

ul.terms {
  padding-left: 1.1rem;
  margin: 0.4rem 0;
}

ul.terms li {
  margin: 0.45rem 0;
}

.note {
  font-size: 0.92rem;
  color: var(--muted);
