button.seal {
  width: 100%;
  background: linear-gradient(180deg, #f03a86, var(--accent));
  color: #fff;
  border: 0;
  border-radius: 10px;
  padding: 14px 16px;
  font-size: 1.05rem;
  letter-spacing: 0.08em;
